-- With no conflict the row is inserted, and its oversized key refused.
-- @setup
CREATE TABLE t (a text, b int);
CREATE INDEX t_a ON t (a);
CREATE UNIQUE INDEX t_b ON t (b);
INSERT INTO t VALUES ('x', 1);
-- @test
-- @expect-error: no conflict, so the row enters the index
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES ('', 2) ON CONFLICT DO NOTHING;
